RULES = dict(
    weekend=[5, 6],
    holidays=["2026-10-26", "2026-11-11", "2026-11-26", "2026-12-25", "2027-01-01"],
    bands=[dict(name="early", lo=1, hi=7, bd=12, attempts=1), dict(name="late", lo=8, hi=45, bd=7, attempts=2)],
)


def pname(p):
    t = str(p.get("type") or "")
    if t == "credit_card":
        return "credit card ending " + " ".join(list(str(p.get("card_last4") or "")))
    if t == "personal_loan":
        return "personal loan"
    if t == "car_loan":
        return "car loan"
    return t.replace("_", " ")


try:
    cal = Calendar(RULES["weekend"], RULES["holidays"])
    now = parse_now(vars.get("now"))
    today = now.date()
    a1 = cal.last_business_day_of_week(today)
    if a1 is None or a1 <= today:
        a1 = cal.last_business_day_of_week(today, 1)
    prods = read_list(vars, "products", "get_account_response.data.products", "fetch_account_response.data.products")
    plan = []
    for i, p in enumerate(prods):
        if not isinstance(p, dict):
            continue
        dl_n = int(p.get("days_late") or 0)
        band = RULES["bands"][0] if dl_n <= RULES["bands"][0]["hi"] else RULES["bands"][1]
        dl = cal.add_business_days(today, band["bd"])
        floor = p.get("minimum_payment") if p.get("type") == "credit_card" else p.get("instalment_amount")
        plan.append(dict(id=str(p.get("product_id") or ("p" + str(i + 1))), name=pname(p), past_due=money(p.get("past_due")),
                         days=dl_n, band=band["name"], attempts=band["attempts"], deadline=dl, floor=money(floor)))
    if not plan:
        raise ValueError("no products")
    sent = ["I am calling from the collections team about a late payment."]
    facts = []
    for n, p in enumerate(plan):
        sent.append("Your " + p["name"] + " has " + p["past_due"] + " past due and is " + str(p["days"]) + " days late.")
        f = ("PRODUCT %d: product_id=%s, say it as \"%s\". Full past-due amount %s. %d days late, %s band. "
             "DEADLINE (latest allowed promise date, inclusive): %s (%s). FLOOR (lowest acceptable amount): %s. "
             % (n + 1, p["id"], p["name"], p["past_due"], p["days"], p["band"], spoken(p["deadline"]), p["deadline"].isoformat(), p["floor"]))
        if p["attempts"] == 1:
            f += ("You may make ONE persuasion attempt for this product: attempt 1 = the full amount %s (or the floor %s if the customer already said the full amount is too much) on %s (%s). "
                  "After that is refused, stop: note reason refused." % (p["past_due"], p["floor"], spoken(a1), a1.isoformat()))
        else:
            f += ("You may make TWO persuasion attempts for this product: attempt 1 = the full amount %s (or the floor %s if the customer already said the full amount is too much) on %s (%s); "
                  "attempt 2 = the floor %s on the deadline %s (%s). After both are refused, stop: note reason refused."
                  % (p["past_due"], p["floor"], spoken(a1), a1.isoformat(), p["floor"], spoken(p["deadline"]), p["deadline"].isoformat()))
        facts.append(f)
    if len(plan) == 1:
        sent.append("Can you make this payment today?")
    else:
        sent.append("Can you make all of these payments today?")
    vars["debt_statement"] = " ".join(sent)
    vars["account_facts"] = "\n".join(facts)
    vars["product_count"] = str(len(plan))
    latest = max(p["deadline"] for p in plan)

    def answer(d):
        parts = []
        for p in plan:
            if d < today:
                parts.append(p["id"] + ": in the past, ask for another day")
            elif d > p["deadline"]:
                parts.append(p["id"] + ": AFTER its deadline, the latest date is " + spoken(p["deadline"]) + " (" + p["deadline"].isoformat() + "), offer that")
            elif not cal.is_business_day(d):
                nd = cal.next_business_day(d)
                if nd > p["deadline"]:
                    nd = p["deadline"]
                parts.append(p["id"] + ": not a business day, offer " + spoken(nd) + " (" + nd.isoformat() + ")")
            else:
                parts.append(p["id"] + ": accept " + d.isoformat())
        return "; ".join(parts)

    vars["date_answers"] = answer_table(cal, today, (latest - today).days + 10, answer)
except Exception as e:
    vars["debt_statement"] = "I am calling from the collections team about a late payment, but I cannot see your account details right now."
    vars["account_facts"] = "Account facts are not available. Do not state any amount, date or product. Say you do not have the information."
    vars["product_count"] = "0"
    vars["date_answers"] = "Not available."

